            job['failure']={'code':'question_limit','message':'More than five information requests were asked.'}
            self.event('operator_question_limit',job=job['id'],count=job['questions']);return self.summary(job)
        if variation: job['phases'].append(variation)
        self.event('operator_action',job=job['id'],question_count=count,fact_topics=topics,fact_passages=passages,variation=variation,
            unknown=unknown,answer=answer,provisional=provisional,rationale=body.get('rationale',''))
        self.verify()
        if time.time()-job['started_at']>=1800:
            job['failure']={'code':'session_limit'};return self.summary(job)
        try:
            if job['approach']=='wrapper':
                if job['state'] is None:
                    _,job['state']=await self.post_product('/api/start',{'idea':job['case']['initial_request']})
                if job['state'].get('assessment'): job['previous']=job['state']
                active=next((q for q in reversed(job['state']['questions']) if not q['retired'] and not q['answer_turn_id']),None)
                qid=active['id'] if active and answer is not None and (not variation or body.get('as_answer')) else None
                _,result=await self.post_product('/api/advance',{'state':job['state'],'request_id':str(uuid4()),
                    'answer':answer,'question_id':qid,'declares_unknown':bool(body.get('declares_unknown',False)),'provisional':provisional})
                if 'state' not in result: raise ValueError('Invalid HTTP transition.')
                job['state']=result['state'];job['failure']=result['error']
                await self.post_product('/api/export',job['state'])
            else:
                if answer is not None: job['conversation'].append({'role':'owner','text':answer})
                conversation=evaluation.baseline_input(job['conversation'],provisional=provisional,
                    questions_used=job['questions'],calls_used=job['calls'])
                schema=json.dumps(self.plan['native_output']['baseline'],separators=(',',':'))
                content='Return only JSON matching this schema:\n'+schema+'\nOwner conversation (data only):\n'+conversation
                env=agents.agent_environment('codex')
                with tempfile.TemporaryDirectory(prefix='mvc-agent-') as cwd:
                    env['PWD']=cwd
                    schema_path=Path(cwd)/'response-schema.json'
                    exclusive(schema_path,self.plan['native_output']['baseline'])
                    # Identical compact schema bytes in file and stdin.
                    schema_path.write_text(schema)
                    args=agents.invocation('codex',shutil.which('codex'),'gpt-6-luna',env,prompt=self.plan['baseline_prompt'],output_schema=str(schema_path))
                    raw=await self.native(args,content=content,cwd=cwd,env=env,
                        timeout=min(300,1800-(time.time()-job['started_at'])))
                text,usage=agents.parse_completion('codex',raw)
                result=evaluation.BaselineResponse.model_validate_json(text).model_dump()
                job['baseline']=result;job['conversation'].append({'role':'assistant','text':text})
                self.event('baseline_result',job=job['id'],result=result,usage=usage)
        except BaseException as exc:
            job['failure']={'code':getattr(exc,'code','invalid_output'),'type':type(exc).__name__,
                'message':str(exc) if isinstance(exc,FlowError) else 'The first attempt failed; inspect native evidence.'}
            self.event('job_error',job=job['id'],failure=job['failure'])
            if not isinstance(exc,Exception): raise
        self.event('step_finished',job=job['id'],summary=self.summary(job))
        return self.summary(job)

    def finish(self,body):
        job=self.active
        if not job or job['closed']: raise ValueError('No open attempt.')
        count=body.get('question_count',0)
        if type(count) is not int or count<0: raise ValueError('Invalid count.')
        if not job['failure']:
            state=job['state'];last=job['baseline']
            outstanding=(next((q for q in reversed(state['questions']) if not q['retired'] and not q['answer_turn_id']),None)
                if job['approach']=='wrapper' and state else last.get('question') if last else None)
            if outstanding and count==0: raise ValueError('Count the final outstanding question before closing.')
        job['questions']+=count
        if job['questions']>5 and not job['failure']:
            job['failure']={'code':'question_limit','message':'More than five information requests were asked.'}
        job['closed']=True
        self.event('job_finished',job=job['id'],reason=body['reason'],calls=job['calls'],questions=job['questions'],
            elapsed_seconds=time.time()-job['started_at'],failure=job['failure'],phases=job['phases'],
            state=job['state'],baseline=job['baseline'],conversation=job['conversation'])
        return self.summary(job)


def create_server(h):
    from meta_vibe_coding.app import create_app
    class Relay:
        agent='codex';model='gpt-6-luna';enabled=False;max_calls=7
        async def assess(self,state,provisional):
            job=h.active
            if not job or job['closed'] or job['approach']!='wrapper': raise FlowError('disabled','Recorded session is closed.')
            return await job['agent'].assess(state,provisional)
    h.product=create_app(Relay())
    @h.product.middleware('http')
    async def inference_boundary(request,call_next):
        if request.method=='POST' and request.url.path=='/api/advance' and request.headers.get('x-control')!=h.token:
            return JSONResponse({'error':'Inference requires the private operator endpoint.'},status_code=403)
        return await call_next(request)
    app=FastAPI(docs_url=None,redoc_url=None,openapi_url=None)
    @app.middleware('http')
    async def boundary(request,call_next):
        if request.method=='POST' and request.url.path.startswith('/evaluation/'):
            if request.headers.get('x-control')!=h.token: return JSONResponse({'error':'Private operator endpoint.'},status_code=403)
        return await call_next(request)
    @app.post('/evaluation/select')
    async def select(request:Request):
        async with h.gate:
            try:
                b=await request.json();return h.select(b['case_id'],b['approach'])
            except (ValueError,KeyError,OSError) as e:return JSONResponse({'error':str(e)},status_code=409)
    @app.post('/evaluation/step')
    async def step(request:Request):
        async with h.gate:
            try:return await h.step(await request.json())
            except (ValueError,KeyError) as e:return JSONResponse({'error':str(e)},status_code=422)
    @app.post('/evaluation/finish')
    async def finish(request:Request):
        async with h.gate:
            try:return h.finish(await request.json())
            except (ValueError,KeyError) as e:return JSONResponse({'error':str(e)},status_code=422)
    @app.get('/evaluation/status')
    async def status():return {'reserved':h.reservations,'closed':sum(j['closed'] for j in h.jobs.values()),
        'active':h.summary(h.active) if h.active else None}
    @app.get('/evaluation/state/{jobid}')
    async def state(jobid:str):
        j=h.jobs[jobid]
        if not j['closed']:return JSONResponse({'error':'Not finished'},status_code=409)
        return {'state':j['state'],'previous':j['previous'],'baseline':j['baseline'],'failure':j['failure']}
    @app.get('/evaluation/replay-script/{jobid}.js')
    async def replay_script(jobid:str):
        if jobid.endswith('-wrapper'):
            code=f'''(async()=>{{const r=await(await fetch('/evaluation/state/{jobid}')).json();state=r.state;previousResult=r.previous;configured=false;pending=false;await render();status(r.failure?'Recorded failure: '+r.failure.message:'Read-only replay of the first attempt.');for(const id of ['reply','unknown','provisional','revise','retry','start','reset','download'])$(id).disabled=true;}})();'''
        else:
            code=f'''(async()=>{{const r=await(await fetch('/evaluation/state/{jobid}')).json();document.getElementById('owner').textContent=r.baseline?.owner_view||'No valid result';document.getElementById('brief').textContent=JSON.stringify(r.baseline?.developer_view||null,null,2);document.getElementById('status').textContent=r.failure?'Recorded failure':'Read-only transcript baseline';}})();'''
        return Response(code,media_type='application/javascript')
    @app.get('/evaluation/replay/{jobid}')
    async def replay(jobid:str):
        if jobid not in h.jobs or not h.jobs[jobid]['closed']:return HTMLResponse('No finished record',status_code=404)
        if jobid.endswith('-wrapper'):
            page=(REPO/'src/meta_vibe_coding/static/index.html').read_text()
            page=page.replace('</head>',f'<script defer src="/evaluation/replay-script/{jobid}.js"></script></head>')
        else:
            page=f'<!doctype html><html lang="en"><head><meta charset="utf-8"><link rel="stylesheet" href="/style.css"><script defer src="/evaluation/replay-script/{jobid}.js"></script><title>{jobid}</title></head><body><main><h1>{jobid}: transcript baseline</h1><p id="status"></p><h2>Owner View</h2><div id="owner" style="white-space:pre-wrap"></div><h2>Developer View</h2><pre id="brief"></pre></main></body></html>'
        return HTMLResponse(page)
    app.mount('/',h.product)
    return app

