        return Response(code,media_type='application/javascript')
    @app.get('/evaluation/replay/{jobid}')
    async def replay(jobid:str):
        if jobid not in h.jobs or not h.jobs[jobid]['closed']:return HTMLResponse('No finished record',status_code=404)
        if jobid.endswith('-wrapper'):
